"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[7137],{4828(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>o,default:()=>c,frontMatter:()=>a,metadata:()=>r,toc:()=>l});var i=n(4848),s=n(8453);const a={},o="Chapter 8: Prose Is Not Content; Code Is Not an Asset",r={id:"AI_TAO/ch08",title:"Chapter 8: Prose Is Not Content; Code Is Not an Asset",description:"AI Did Not Create the Problem",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/AI_TAO/ch08.md",sourceDirName:"AI_TAO",slug:"/AI_TAO/ch08",permalink:"/en/docs/AI_TAO/ch08",draft:!1,unlisted:!1,tags:[],version:"current",frontMatter:{},sidebar:"docs",previous:{title:"Part III: The Demon-Revealing Mirror \u2014 What AI Exposes",permalink:"/en/docs/AI_TAO/ch07"},next:{title:"Chapter 9: The Dead Knot of Corporate Culture",permalink:"/en/docs/AI_TAO/ch09"}},h={},l=[{value:"AI Did Not Create the Problem",id:"ai-did-not-create-the-problem",level:2},{value:"Prose Has Never Been Content",id:"prose-has-never-been-content",level:2},{value:"Frameworks Killed Architectural Thinking \u2014 AI Only Shovelled the Last Scoop of Dirt",id:"frameworks-killed-architectural-thinking--ai-only-shovelled-the-last-scoop-of-dirt",level:2},{value:"Large Systems Will Not Die, but They Will Become Prisons",id:"large-systems-will-not-die-but-they-will-become-prisons",level:2},{value:"What Is Exposed Is Not Weakness \u2014 It Is Truth",id:"what-is-exposed-is-not-weakness--it-is-truth",level:2}];function d(e){const t={code:"code",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",img:"img",p:"p",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(t.header,{children:(0,i.jsx)(t.h1,{id:"chapter-8-prose-is-not-content-code-is-not-an-asset",children:"Chapter 8: Prose Is Not Content; Code Is Not an Asset"})}),"\n",(0,i.jsx)(t.h2,{id:"ai-did-not-create-the-problem",children:"AI Did Not Create the Problem"}),"\n",(0,i.jsx)(t.p,{children:"There is a very popular narrative: AI has changed everything. Jobs will disappear, skills will become obsolete, humans must redefine themselves."}),"\n",(0,i.jsx)(t.p,{children:"The direction of this narrative is not wrong, but it has the causality reversed."}),"\n",(0,i.jsx)(t.p,{children:"AI did not create new problems. What it did is simpler, and more brutal \u2014 it took a pile of problems that had long existed but were always concealed, and spread them all out under the sunlight at once."}),"\n",(0,i.jsx)(t.p,{children:"Prose has never equalled content. Code has never equalled systems thinking. Credentials have never equalled competence. Large systems have never been stable. These were true before AI appeared; it was just that because production costs were high and barriers were high, no one was ever forced to face them."}),"\n",(0,i.jsx)(t.p,{children:"What AI did was drive production costs down to near zero."}),"\n",(0,i.jsx)(t.p,{children:'When anyone can generate a grammatically correct, structurally complete passage of text in seconds, "being able to write" is no longer a scarce capability. When anyone can use AI to build a functional system in a few days, "being able to code" is no longer a source of differentiation. When anyone can use agents to automate an entire workflow, "being able to operate tools" is no longer a competitive advantage.'}),"\n",(0,i.jsx)(t.p,{children:"What remains is a naked question: once you strip away these media, what do you actually have in hand?"}),"\n",(0,i.jsx)(t.p,{children:"Chapter 7 shone its light on education \u2014 how anxiety is packaged into a commodity, how credentials conceal the absence of cognition. This chapter shines its light on the individual: of the things you believed were your abilities, how many were actually just the threshold of the medium?"}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"prose-has-never-been-content",children:"Prose Has Never Been Content"}),"\n",(0,i.jsx)(t.p,{children:'Previously, writing fluent prose was a gated skill. Producing exquisite visuals was too. Editing rhythmically paced video, even more so. These skills required years of training, talent, and the accumulation of experience. Because the barrier was high, we long equated "being able to write" with "having something to say," and "drawing well" with "having something to express."'}),"\n",(0,i.jsx)(t.p,{children:"Prose was content. Draftsmanship was the work. Technique was thought."}),"\n",(0,i.jsx)(t.p,{children:"But prose has never been content. Draftsmanship has never been the work. Technique has never been thought."}),"\n",(0,i.jsx)(t.p,{children:"They are carriers of intention \u2014 pathways through which consciousness finds an outlet. A person who writes well does not necessarily have something to say; but a person who has something to say will find a way to say it \u2014 through text, through images, through sound, through whatever medium is available."}),"\n",(0,i.jsx)(t.p,{children:'AI shattered this long-standing illusion in one blow. When the cost of generating fluent text drops to zero, the gap between "being able to write" and "having something to say" can no longer be hidden.'}),"\n",(0,i.jsx)(t.p,{children:"At the two ends of this crack stand two kinds of people. Chapter 11 will spend more time dissecting them \u2014 a seasoned writer guarding the gate, a power user burning tokens \u2014 and a third possibility more worth noting. For now, remember one thing: prose is a medium, not content. AI has not stolen anyone's livelihood; it has simply made it impossible for anyone to hide behind the medium any longer."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{alt:"Gemini_Generated_Image_1nsftn1nsftn1nsf.jpg",src:n(7328).A+"",width:"1200",height:"2150"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"frameworks-killed-architectural-thinking--ai-only-shovelled-the-last-scoop-of-dirt",children:"Frameworks Killed Architectural Thinking \u2014 AI Only Shovelled the Last Scoop of Dirt"}),"\n",(0,i.jsx)(t.p,{children:"Chapter 7 described a distortion in education: the examination system trains problems that require judgement into problems solvable by memory, so engineers learn to operate, not to think."}),"\n",(0,i.jsx)(t.p,{children:"The same distortion played out in another form in software engineering, twenty years ahead of schedule. And the culprit was not AI \u2014 it was frameworks."}),"\n",(0,i.jsx)(t.p,{children:"Around 2004, frameworks like Rails, React, and Spring began to spread. What is a framework, fundamentally? A pre-packaged set of design judgements. Using React means accepting its decisions on state management. Using Rails means accepting its MVC architecture and its philosophy of convention over configuration. You do not need to know why it was designed that way; you just need to follow."}),"\n",(0,i.jsx)(t.p,{children:'What frameworks sell is: "You can produce something without needing a holistic view."'}),"\n",(0,i.jsx)(t.p,{children:'From that moment, "understanding the fundamentals" was demoted from an entry requirement to a senior bonus. Most developers no longer needed to make architectural decisions, because the framework had made them for them. They became operators of the framework \u2014 highly proficient, but the moment the framework updated or the technology pivoted, their experience reset to zero. They learned to operate, not to think. The educational distortion described in Chapter 7 played out twenty years earlier in software engineering, in the form of frameworks.'}),"\n",(0,i.jsx)(t.p,{children:'AI delivered the second blow. In the framework era, you at least still needed to judge "which framework to use," "how to connect frameworks," and "when not to use a framework." In the AI era, even this layer of judgement can be outsourced to an agent. You say two sentences to an agent and get runnable code; you never even have the chance to experience the deep understanding that comes from "why did it break."'}),"\n",(0,i.jsx)(t.p,{children:"Lay this timeline out, and you see a complete history of abstraction: compilers eliminated the need to write assembly language. Garbage collection eliminated the need to manage memory. Frameworks eliminated the need to do architectural design. AI eliminates the need to write code. Each round of abstraction is an outsourcing of holistic understanding. AI is not an anomaly; it is merely the latest node on this line."}),"\n",(0,i.jsx)(t.p,{children:"But here is a cruel question: AI removed the pain, but pain was once the vehicle of education."}),"\n",(0,i.jsx)(t.p,{children:"How did engineers of the past develop holistic understanding? By debugging until dawn, by breaking the system themselves and fixing it, by being tormented by legacy code, by watching a bad design decision explode three years later. All of these were friction. And what AI excels at is eliminating friction."}),"\n",(0,i.jsx)(t.p,{children:"The result is a structural fault line: those with judgement grew up in an environment without AI \u2014 they went through that painful tempering. The next generation, growing up with AI, skips that tempering entirely. People with judgement will become fewer and fewer, yet market demand for judgement \u2014 because output volume has exploded and someone needs to judge quality and direction \u2014 is rising."}),"\n",(0,i.jsx)(t.p,{children:"AI did not kill architectural thinking. Architectural thinking died at the hands of frameworks, and has been dead for over a decade. AI only shovelled the last scoop of dirt on the corpse, and only then did everyone notice the grave had been there for a long time."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{alt:"Gemini_Generated_Image_ya0usjya0usjya0u.jpg",src:n(3942).A+"",width:"1200",height:"2150"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"large-systems-will-not-die-but-they-will-become-prisons",children:"Large Systems Will Not Die, but They Will Become Prisons"}),"\n",(0,i.jsx)(t.p,{children:"If frameworks killed the individual engineer's holistic understanding, then the acceleration of technological iteration is changing the nature of something else: large systems."}),"\n",(0,i.jsx)(t.p,{children:"Previously, building a large system was worth doing. ERPs, CRMs, enterprise back-ends \u2014 these things had lifespans of five, ten, twenty years. Build costs were high, but maintenance costs were relatively low, and the systems became more stable with use. Enterprises were willing to spend heavily to build and maintain them, because the investment payback horizon was long enough."}),"\n",(0,i.jsx)(t.p,{children:"Today, the pace of technological iteration has accelerated to the point of changing this equation. Models turn over every six months. Frameworks every year. Cloud platforms update APIs every quarter. You have not finished reading the last version's documentation before the next is released. Systems are not depreciating \u2014 they are evaporating \u2014 the same structure as the knowledge evaporation described in Chapter 7."}),"\n",(0,i.jsx)(t.p,{children:"But large systems will not disappear because of this. Enterprises still need them. A bank's core transaction system cannot be assembled from microservices; a hospital's electronic health records cannot be rewritten every six months; a factory's MES cannot go offline because a cloud API was revised. Large systems will continue to exist, only their nature has changed \u2014 from an asset, they are gradually becoming an increasingly expensive prison. You cannot leave it, but maintaining it costs ever more; you want to replace it, but the risk and cost of replacement exceed those of maintenance."}),"\n",(0,i.jsx)(t.p,{children:"\"Increasingly expensive\" is not rhetoric. Industry benchmarks from Gartner, Forrester, and Deloitte consistently indicate that legacy system maintenance accounts for 60\u201380% of enterprise IT total expenditure, leaving only 20\u201340% for innovation and new feature development. The US Government Accountability Office (GAO) 2025 report quantified an extreme case: of the federal government's annual IT budget exceeding $105 billion, 79% was allocated to operations and maintenance. And by 2026, maintenance costs are climbing at 18\u201325% per year \u2014 senior developers who understand legacy systems are retiring, and what they take with them is not syntax knowledge, which can be documented; they take decades of business judgement compressed into intuition \u2014 which corner cases will explode during month-end settlement, which field formats conceal a regulatory requirement from fifteen years ago, which seemingly redundant logic is actually stopping a bullet only they have ever seen. 70% of organisations still struggle to find multi-skilled mainframe talent (Kyndryl / BMC, 2025). The pressure of security-vulnerability patching mounts, and the interest on technical debt never stops accruing. This is not a metaphor for a prison. This is the prison's bill."}),"\n",(0,i.jsx)(t.p,{children:"The prison bill is not even the cruelest part. The cruelest part: you cannot even use AI to escape."}),"\n",(0,i.jsx)(t.p,{children:"Approximately 220 billion lines of COBOL remain in operation globally. It handles 95% of ATM transactions, 80% of in-person credit card transactions, and clears over $3 trillion daily. 43% of banking systems are built on COBOL (World Economic Forum; Open Mainframe Project, 2025). This is not a marginal issue \u2014 it is the baseplate of financial infrastructure."}),"\n",(0,i.jsx)(t.p,{children:"Enterprises, of course, want to escape. AI-driven migration tools are being deployed at scale to address this, claiming extremely high business-logic preservation rates and 60\u201390% cost reductions. The quality of syntactic translation is indeed remarkable \u2014 AI-generated Java code is nearly always syntactically correct, structurally complete, and compilable. Then it crashes repeatedly during user-acceptance testing."}),"\n",(0,i.jsx)(t.p,{children:"Where does it crash? On things AI cannot see."}),"\n",(0,i.jsxs)(t.p,{children:["A variable called ",(0,i.jsx)(t.code,{children:"TRN-LIMIT"})," \u2014 not defined in the source file being translated, but buried in a COPYBOOK thousands of lines earlier in the execution chain \u2014 contains a ",(0,i.jsx)(t.code,{children:"REDEFINES"})," clause. This is a COBOL construct: the same memory address, depending on a flag set in a completely different module, is interpreted as two different data types. AI treated it as an ordinary numeric field. The result: the Java application wrote corrupted binary data into a database field. The code compiled. The test environment ran. The data silently corrupted where no one was watching."]}),"\n",(0,i.jsx)(t.p,{children:"This is not an isolated case. Gartner noted that of mainframe exit projects initiated in 2026, over 70% are expected to fail to achieve their intended benefits \u2014 and the failure causes are almost entirely structural: hidden dependencies, shared memory mappings, mainframe-specific integration layers (CICS, Db2) \u2014 not syntax errors. The quality of translation was never the bottleneck. Code that compiles is the easy part. The hard part is the code the tool cannot see \u2014 compressed into COPYBOOKs, scattered across the execution chain, known only to people who have used the system for twenty years. AI translates syntax. But the real value of a COBOL system is not in its syntax. It is in decades of accumulated business judgement, in corner cases that were never documented. AI can perfectly translate what it can see, but what it cannot see is what the system is actually doing."}),"\n",(0,i.jsx)(t.p,{children:"You are not merely unable to leave the old system. You cannot even use AI to escape \u2014 because AI translates code, not judgement."}),"\n",(0,i.jsx)(t.p,{children:'This prison effect is being experienced across the industry. Some have tried to break free \u2014 over a decade ago, "microservices" were promoted as the cure, splitting large systems into dozens or hundreds of independent small services, each developed and deployed separately. It sounded beautiful. But in practice, most enterprises discovered that managing hundreds of microservices (service mesh, distributed transactions, observability, version compatibility) was even more painful than the original large system.'}),"\n",(0,i.jsx)(t.p,{children:"Numbers speak more clearly than metaphors. A 2025 CNCF (Cloud Native Computing Foundation) survey found that 42% of organisations that adopted microservices are consolidating services back into larger deployment units \u2014 citing debugging complexity, operational overhead, and network latency. Gartner's figures are bleaker: 60% of teams regret using microservices in small-to-medium applications; monolithic architectures save an average of 25% in costs. Even Amazon \u2014 the company that essentially invented modern cloud architecture \u2014 rolled its Amazon Prime Video monitoring service back from microservices to a monolith, reducing infrastructure costs by 90%. Segment rolled back from over 150 microservices to a single application. Service mesh adoption rates dropped from 18% to 8%. Microservices as a universal cure for enterprise architecture have essentially failed. Many companies are quietly retracing their steps \u2014 not because monoliths are trendier, but because the complexity tax of microservices costs more than the problems they solve."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{alt:"Gemini_Generated_Image_eu8777eu8777eu87.jpg",src:n(1503).A+"",width:"1200",height:"2150"})}),"\n",(0,i.jsx)(t.p,{children:"So is the problem unsolvable?"}),"\n",(0,i.jsx)(t.p,{children:"One case provides a different angle of observation, but the reason it works is precisely because the conditions are extremely specific \u2014 what is worth dissecting is not the method, but the premises."}),"\n",(0,i.jsx)(t.p,{children:"A few years ago, someone built a work system linking multiple small programmes together. He had originally considered building a large system \u2014 unified architecture, centralised management, one system to rule them all. But the revision speed of cloud platforms forced him to reassess that judgement. Google's GCP and Firebase kept updating APIs; he had to keep chasing documentation updates, keep feeding them to AI, keep adjusting. The effort spent keeping up was routinely nine or ten times the actual development effort. He thought he was maintaining a system; in reality, the cloud platform was leading him by the nose."}),"\n",(0,i.jsx)(t.p,{children:"It was precisely this experience that led him to make a deliberate architectural decision: divide and conquer. Stop building large systems; instead, make every tool small enough to rewrite with AI at any time, small enough that if it expires, there is nothing to mourn. Later the master system expired, and he did not rebuild it \u2014 not because he could not, but because he had already judged it was not worth it. Those small programmes did not need a huge master system to coordinate them."}),"\n",(0,i.jsx)(t.p,{children:"But the reason this works is two very specific premises: he is a single person, with no need for cross-team collaboration; and his workflow does not require a unified central system. In a ten-person team scenario requiring shared state and consistency guarantees, this approach simply does not work. Enterprises need large systems not because they are foolish, but because the collaboration complexity they face is completely different from that of one person."}),"\n",(0,i.jsx)(t.p,{children:'So the real insight is not "small is better than big" \u2014 that proposition holds only under extremely specific conditions. The real insight is: when build costs approach zero because of AI, what is the real asset?'}),"\n",(0,i.jsx)(t.p,{children:"The answer is not code. Code expires. Not frameworks. Frameworks update. Not platforms. Platforms get revised."}),"\n",(0,i.jsx)(t.p,{children:'The real asset is the judgement of knowing "what the system should look like." It is the ability, when facing infinitely many possible architectures, to know which one suits the current constraints, which one will hit a wall in three months, which one sacrifices what in exchange for what.'}),"\n",(0,i.jsx)(t.p,{children:"AI can generate ten architectural options in an hour. But who decides which one to pick?"}),"\n",(0,i.jsx)(t.p,{children:"This brings us back to the cognitive fault line described in Chapter 7. The person capable of making this judgement \u2014 their ability is not in any piece of code, not in any framework, not on any certificate. It is in their cognitive model \u2014 a system of trade-offs compressed from years of experience. This system is extraordinarily valuable, but in the language of r\xe9sum\xe9s, KPIs, and training systems, it remains invisible."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{alt:"Gemini_Generated_Image_9uf0xm9uf0xm9uf0.jpg",src:n(5042).A+"",width:"1200",height:"2150"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.h2,{id:"what-is-exposed-is-not-weakness--it-is-truth",children:"What Is Exposed Is Not Weakness \u2014 It Is Truth"}),"\n",(0,i.jsx)(t.p,{children:"Place these things side by side, and a common pattern emerges."}),"\n",(0,i.jsx)(t.p,{children:"AI exposed the truth about writing: prose is not content; consciousness is. AI exposed the truth about programming: operation is not competence; architectural thinking is \u2014 and architectural thinking was already declining before AI. AI exposed the truth about systems engineering: code is not an asset; the judgement of knowing what to build and what not to build is. AI exposed the truth about education: credentials are not cognition; judgement is."}),"\n",(0,i.jsx)(t.p,{children:"In every domain, AI does the same thing: it drives production costs to zero, then forces everyone to face a fact that had long been concealed by high production costs \u2014 what is truly valuable has never been at the production layer."}),"\n",(0,i.jsx)(t.p,{children:'Previously, you could hide behind "I can write," "I can draw," "I can code," "I have a certificate," because the scarcity of these skills alone was enough to sustain you. Now these shields have been removed, and the person standing behind them \u2014 whether they have something to say, whether they have judgement, whether they have cognitive depth \u2014 is fully exposed.'}),"\n",(0,i.jsx)(t.p,{children:"This is not a crisis. This is a demon-revealing mirror."}),"\n",(0,i.jsx)(t.p,{children:"And what the mirror reveals is not only the substance and void of individuals. Every problem discussed above \u2014 the hollowness hiding behind prose, the operators hiding inside frameworks, the teams locked inside large systems \u2014 they do not happen in a vacuum. They happen inside companies. Inside meeting rooms. On performance review sheets and org charts."}),"\n",(0,i.jsx)(t.p,{children:"The covers over individuals have been lifted by AI. But the covers over corporations \u2014 things that have operated for decades on discourse power, definitional authority, titles, and processes \u2014 lifting those requires not a better tool, but a larger mirror."}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.img,{alt:"Gemini_Generated_Image_rxllj9rxllj9rxll.jpg",src:n(7708).A+"",width:"1200",height:"2150"})}),"\n",(0,i.jsx)(t.hr,{}),"\n",(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"AI exposed the substance and void of individuals. But when the same mirror shines into the corporation, what it reveals is even harder to look at."})})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},7328(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_1nsftn1nsftn1nsf-a1ef42bae324a76c922b58395e5b1624.jpg"},5042(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_9uf0xm9uf0xm9uf0-3f67e95c4f0ed7cb6c341a137d57ce44.jpg"},1503(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_eu8777eu8777eu87-1e54c53d0edea639dbb9547d6166ff3e.jpg"},7708(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_rxllj9rxllj9rxll-ce9f67537ea99670f879f880db5b18c4.jpg"},3942(e,t,n){n.d(t,{A:()=>i});const i=n.p+"assets/images/Gemini_Generated_Image_ya0usjya0usjya0u-22ab1590a34f0989a7e230b032b4f86b.jpg"},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var i=n(6540);const s={},a=i.createContext(s);function o(e){const t=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:o(e.components),i.createElement(a.Provider,{value:t},e.children)}}}]);